(1, 'All Inventory Users', 'all_users', 'system', 'shared', NULL, 0, NULL, 1, 'All teachers with inventory access. Used for system-wide announcements, policy updates, and scheduled inventory audits.', 1, '2026-04-16 03:47:52', '2026-05-05 06:57:22', '2026-05-05 06:57:22'),
(2, 'Inventory Administrators', 'role', 'system', 'shared', NULL, 0, NULL, NULL, 'Inventory admin teachers and system supervisors. Receives approval notifications, exception handling alerts, and system configuration changes.', 1, '2026-04-16 03:47:52', '2026-04-16 03:47:52', NULL),
(3, 'Science Department', 'department', 'system', 'shared', NULL, 0, 'Science', NULL, 'Science department teachers. Receives equipment availability, department-specific stock updates, and tool sharing coordination.', 1, '2026-04-16 03:47:52', '2026-04-16 03:47:52', NULL),
(4, 'ICT Department', 'department', 'system', 'shared', NULL, 0, 'ICT', NULL, 'ICT department teachers. Receives equipment availability, department-specific stock updates, and tool sharing coordination.', 1, '2026-04-16 03:47:52', '2026-04-16 03:47:52', NULL),
(5, 'TLE / Workshop Department', 'department', 'system', 'shared', NULL, 0, 'TLE', NULL, 'TLE/Workshop department teachers. Receives equipment availability, department-specific stock updates, and tool sharing coordination.', 1, '2026-04-16 03:47:52', '2026-04-16 03:47:52', NULL),
(6, 'Engineering / Lab Department', 'department', 'system', 'shared', NULL, 0, 'Engineering', NULL, 'Engineering/Lab department teachers. Receives equipment availability, department-specific stock updates, and tool sharing coordination.', 1, '2026-04-16 03:47:52', '2026-04-16 03:47:52', NULL),
(7, 'Equipment Custodians', 'role', 'system', 'shared', NULL, 0, NULL, NULL, 'Teachers assigned as custodians of tools/equipment. Receives maintenance reminders, calibration schedules, and asset condition updates.', 1, '2026-04-16 03:47:52', '2026-04-16 03:47:52', NULL),
(8, 'Borrowing & Issuance Officers', 'role', 'system', 'shared', NULL, 0, NULL, NULL, 'Teachers authorized to issue or receive equipment. Receives pending borrow requests, overdue item alerts, and return confirmations.', 1, '2026-04-16 03:47:52', '2026-04-16 03:47:52', NULL),
(9, 'Inventory Audit Committee', 'role', 'system', 'shared', NULL, 0, NULL, NULL, 'Assigned auditing teachers. Receives audit schedules, discrepancy reports, and inventory reconciliation notices.', 1, '2026-04-16 03:47:52', '2026-04-16 03:47:52', NULL),
(10, 'Maintenance & Repair Coordinators', 'role', 'system', 'shared', NULL, 0, NULL, NULL, 'Teachers overseeing repairs or maintenance. Receives damaged equipment alerts, repair status updates, and replacement recommendations.', 1, '2026-04-16 03:47:52', '2026-04-16 03:47:52', NULL),
(11, 'Emergency / Critical Assets Group', 'role', 'system', 'shared', NULL, 0, NULL, NULL, 'Teachers responsible for high-value or safety-critical assets. Receives immediate alerts for loss, damage, safety issues, and high-priority notifications.', 1, '2026-04-16 03:47:52', '2026-04-16 03:47:52', NULL),
(12, 'Filipino Club', 'custom', 'user', 'shared', 1, 0, NULL, NULL, 'as[doshd', 1, '2026-05-04 22:10:05', '2026-05-15 22:58:01', NULL),
(13, 'Gangsta', 'role', 'user', 'shared', 2, 0, NULL, NULL, NULL, 1, '2026-05-17 01:34:45', '2026-05-17 01:34:45', NULL);

