--
-- Table structure for table `inventory_items`
--

CREATE TABLE `inventory_items` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `category_id` bigint(20) UNSIGNED NOT NULL,
  `item_name` varchar(255) NOT NULL,
  `serial_number` varchar(255) NOT NULL,
  `property_number` varchar(255) DEFAULT NULL,
  `unit` varchar(255) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `item_image` varchar(255) DEFAULT NULL,
  `condition` enum('excellent','good','fair','poor','damaged') NOT NULL DEFAULT 'good',
  `disposal_date` date DEFAULT NULL,
  `disposal_reason` text DEFAULT NULL,
  `status` enum('available','borrowed','distributed','maintenance','damaged','archived','disposed','lost','ready_for_disposal') DEFAULT 'available',
  `date_acquired` date DEFAULT NULL,
  `unit_price` decimal(12,2) DEFAULT NULL,
  `source_of_fund` varchar(255) DEFAULT NULL,
  `remarks` text DEFAULT NULL,
  `lifespan_years` int(11) DEFAULT 5,
  `location` varchar(255) DEFAULT NULL,
  `custom_attributes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`custom_attributes`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `deleted_by` bigint(20) UNSIGNED DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

